head.script:
// 테스트 설명, 유효성 값 설정
//  - _1 : inputType(select / checkcombobox / autoComplete) x closeonmouseleave(미설정 / true / false) + 리스트창 닫힌 뒤 편집 상태
//  - _2 : GridViewItemSet 아이템 정의, inputType=select + embeddedInput=true
scwin.tData = {
    "description" : "[column > P > closeonmouseleave]<br/>아이템 리스트창이 표시된 Column 에서 마우스가 해당 영역을 벗어날때 아이템 리스트창을 닫을지 설정합니다.",
    "validation" : [
        "Column 의 inputType='select', 'checkcombobox', 'autoComplete' 인 경우에 동작합니다.",
        "미설정 시, 마우스가 아이템 리스트창과 Cell 영역을 벗어나도 아이템 리스트창을 유지합니다.",
        "true 설정 시, 마우스가 아이템 리스트창과 Cell 영역을 벗어나면 아이템 리스트창이 자동으로 닫힙니다.",
        "false 설정 시, 마우스가 아이템 리스트창과 Cell 영역을 벗어나도 아이템 리스트창을 유지합니다.",
        "Column 의 inputType='checkcombobox' 이면 아이템 리스트창이 닫히면서 Cell 편집도 종료되고 체크한 아이템이 Cell 값에 반영됩니다.",
        "Column 의 inputType='select', 'autoComplete' 이면 아이템 리스트창만 닫히고 Cell 편집 상태는 유지됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (true)
    con_closeonmouseleave.setValue("2");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 행 데이터 (아이템 1월 ~ 6월, value 1 ~ 6 / checkcombobox 다중 선택값은 기본 구분자 공백)
scwin.rowPattern = [
    { "name" : "Row 0", "sel" : "1", "chk" : "1", "auto" : "1" },
    { "name" : "Row 1", "sel" : "2", "chk" : "2 4", "auto" : "3" }
];



// 상태 감시 타이머 / 직전 상태
scwin.watchTimer = null;
scwin.lastState = null;



// 페이지 이탈 시 감시 타이머 정리
scwin.onpageunload = function () {
    scwin.stopWatch();
};



// 감시 타이머 정리
scwin.stopWatch = function () {
    if (scwin.watchTimer) {
        clearInterval(scwin.watchTimer);
        scwin.watchTimer = null;
    }
    scwin.lastState = null;
}



// comp 생성
//  - sel / chk / auto : 검증 대상 Body Column (inputType=select / checkcombobox / autoComplete, 아이템 1월 ~ 6월)
//  - 100ms 감시 타이머 : 리스트창 표시 여부 / 편집 상태 / 셀 값이 바뀌면 결과창에 출력 (마우스 위치와 무관)
scwin.comp_init = async function () {
    // 기존 감시 타이머 / target / dataList / label 삭제
    scwin.stopWatch();
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cCloseonmouseleave = con_closeonmouseleave.getText();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] 셀 더블클릭으로 아이템 리스트창 열기 (checkcombobox 는 아이템 체크) -> 마우스를 리스트창과 셀 밖으로 이동 (위 / 아래 / 왼쪽 / 오른쪽 어느 방향이든)\n[확인] 리스트창 표시/닫힘, 편집 상태, 셀 값이 바뀌는 시점마다 결과창에 자동 출력 (마우스 위치와 무관, 버튼 클릭은 Cell 편집을 종료시키므로 확인 수단으로 쓰지 않음)"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="sel" name="sel" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="auto" name="auto" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowPattern, false);

    // 아이템 정의 (일반 item)
    let strItems = '<w2:choices>';
    for (let i = 1; i <= 6; i++) {
        strItems += '<w2:item><w2:label>' + i + '월</w2:label><w2:value>' + i + '</w2:value></w2:item>';
    }
    strItems += '</w2:choices>';

    // 검증 대상 Column 공통 속성
    let attrClose = (cCloseonmouseleave === '') ? '' : ' closeonmouseleave="' + cCloseonmouseleave + '"';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:630px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="column2" value="sel (select)"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="column3" value="chk (checkcombobox)"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="column4" value="auto (autoComplete)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="name" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="select" id="sel" value=""' + attrClose + '>' + strItems + '</w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="checkcombobox" id="chk" value=""' + attrClose + '>' + strItems + '</w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="autoComplete" id="auto" value=""' + attrClose + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 상태 감시 시작 (생성 직후 상태를 기준값으로 저장, 출력은 변화 시에만)
    scwin.lastState = scwin.getState();
    scwin.watchTimer = setInterval(scwin.watchState, 100);
}



// 현재 상태 (포커스 셀 / 리스트창 표시 여부 / 편집 상태 / 셀 값)
scwin.getState = function () {
    let rowIndex = target1.getFocusedRowIndex();
    let colID = target1.getFocusedColumnID();
    return {
        "rowIndex" : rowIndex,
        "colID" : colID,
        "listVisible" : scwin.isItemListVisible(),
        "editing" : target1.isEditing(),
        "cellValue" : (rowIndex > -1 && colID) ? dlt_bind.getCellData(rowIndex, colID) : ""
    };
}



// 표시 중인 target1 아이템 리스트창 존재 여부
scwin.isItemListVisible = function () {
    let divs = document.querySelectorAll("div[id^='G_" + target1.id + "_'][id$='_itemTable']");
    for (let i = 0; i < divs.length; i++) {
        let style = window.getComputedStyle(divs[i]);
        if (style.display !== "none" && style.visibility !== "hidden" && divs[i].offsetHeight > 0) {
            return true;
        }
    }
    return false;
}



// validation 1 ~ 6 판정 출력 : 리스트창 표시/닫힘, 편집 상태, 셀 값 중 하나라도 바뀐 시점의 상태 (100ms 감시)
//  - 리스트창 닫힘과 편집 종료 사이에 시차가 있으면 각각 1줄씩 출력된다
//  - 편집도 리스트창도 없는 상태끼리의 변화(단순 셀 포커스 이동)는 출력하지 않는다
scwin.watchState = function () {
    if (typeof target1 === 'undefined' || !target1 || !scwin.lastState) {
        return;
    }
    let cur = scwin.getState();
    let prev = scwin.lastState;
    if (cur.rowIndex === prev.rowIndex && cur.colID === prev.colID && cur.listVisible === prev.listVisible
        && cur.editing === prev.editing && cur.cellValue === prev.cellValue) {
        return;
    }
    scwin.lastState = cur;
    if (!cur.listVisible && !cur.editing && !prev.listVisible && !prev.editing) {
        return;
    }
    wf_body_bottom.getObj("scwin").setReturnValue(cur.colID + " 셀 (Row " + cur.rowIndex + ") -> 리스트창 : " + (cur.listVisible ? "표시" : "닫힘") + " / 편집 상태 : " + cur.editing + " / 셀 값 : '" + cur.cellValue + "'");
}
